import {Runtime} from './lib/runtime.mjs';import {seedMemory} from './lib/policy.mjs';
export function createDemo(){let memories=structuredClone(seedMemory),audit=[],listeners=[];const storage={read:()=>structuredClone(memories),add:(record,active)=>{if(active())memories.push(record)},audit:event=>audit.push(event)};const runtime=new Runtime({storage,emit:event=>listeners.forEach(fn=>fn(event)),model:async(history,signal)=>{await new Promise((resolve,reject)=>{const t=setTimeout(resolve,700);signal.addEventListener('abort',()=>{clearTimeout(t);reject(new Error('Cancelled'))},{once:true})});const text=history.at(-1).content,lower=text.toLowerCase();if(lower.startsWith('remember exactly:')){try{return {action:{tool:'save_memory',args:JSON.parse(text.slice(17))}}}catch{}}
 if(/delete|remove all|shell|execute command/.test(lower))return {action:{tool:'delete_memory',args:{id:'all'}}};if(/remember|save.*memory/.test(lower))return {action:{tool:'save_memory',args:{title:'A new priority',content:text.replace(/^remember (that )?/i,'')}}};if(/aegis|policy|permission/.test(lower))return {action:{tool:'search_memory',args:{query:'AEGIS'}}};if(/voice|rime|interrupt/.test(lower))return {action:{tool:'search_memory',args:{query:'voice'}}};if(/memory|graph|search/.test(lower))return {action:{tool:'search_memory',args:{query:''}}};return {text:'I’m NOVA. In this browser demo, I can search the sample knowledge graph, propose a memory for approval, and demonstrate interruptions. Try “Search memory for voice” or “Remember my next priority”. The Electron app connects this same workspace to your local Qwen model and Rime speech.'}}});return {send:text=>runtime.run(text),cancel:()=>runtime.cancel(),approve:(id,yes)=>runtime.approve(id,yes),memory:()=>storage.read(),audit:()=>audit,status:async()=>({mode:'demo'}),configure:async()=>{throw new Error('Connections are available in the Electron desktop app.')},heard:id=>runtime.heard(id),onEvent:fn=>{listeners.push(fn);return ()=>listeners=listeners.filter(x=>x!==fn)},runtime}}
